"""Tests for hairproperties.py: how a dynamic property finds what it drives, the persisted card and bake
settings (including the migration of files saved by older versions) and the getters/setters themselves.

The getters and setters are tested on small hand made objects, the same shape the asset pack objects have, so
the asset pack is not needed here.
"""

import itertools
import json
import os

import bpy
import pytest

from .haireditor_fixtures import (hairproperties as hp, cardgenerators as cg, HAIR_PROPERTIES, FUR_PROPERTIES,
                                  scratch, link, make_grid, make_material)

Factory = hp.HairGetterSetterFactory

_ASSET_NUMBERS = itertools.count()


@pytest.fixture
def asset_name():
    """A name no other test uses. Dynamic properties are registered on the Object type, so names have to be unique."""
    return f"hptest{next(_ASSET_NUMBERS)}_{os.getpid()}"


@pytest.fixture
def stand_in(scratch, asset_name):
    """A plain mesh standing in for the basemesh the settings are stored on."""
    obj = link(bpy.data.objects.new(f"{asset_name}_body", bpy.data.meshes.new(f"{asset_name}_body")))
    yield obj
    for config_set in (HAIR_PROPERTIES, FUR_PROPERTIES):
        config_set.remove_dynamic_keys_with_prefix(f"{asset_name}_", obj)


def _child(parent, name, data=None):
    obj = link(bpy.data.objects.new(name, data if data is not None else bpy.data.meshes.new(name)))
    obj.parent = parent
    return obj


def _rna_type(obj, config_set, name):
    return obj.bl_rna.properties[f"{config_set.dynamic_prefix}{name}"].type


# ---------------------------------------------------------------------------
# Working out what a dynamic property drives, from its name alone
