def test_hair_slider_is_recognised():
    factory = Factory("DHAI_bob_length")
    assert factory.is_hair_property
    assert not factory.is_cards_property
    assert factory.short_property_name == "length"
    assert factory.hair_object_name == "bob"
    assert (factory.modifier_name, factory.modifier_attribute) == ("Set Hair Curve Profile", "Socket_1")
    assert (factory.min, factory.max) == (0.0, 10.0)
    assert factory.default_value == factory.min


def test_longest_matching_hair_slider_wins():
    """"roll_length" also ends with "length", the more specific one has to be picked."""
    factory = Factory("DHAI_bob_roll_length")
    assert factory.short_property_name == "roll_length"
    assert factory.hair_object_name == "bob"


def test_card_settings_are_not_mistaken_for_hair_sliders():
    """"cards_density" also ends with the hair slider "density"."""
    factory = Factory("DHAI_bob_cards_density")
    assert factory.is_cards_property
    assert not factory.is_hair_property
    assert factory.socket_name == "Density"
    assert factory.default_value == 0.01
    assert factory.hair_object_name == "bob"


def test_card_setting_with_a_longer_name_wins():
    factory = Factory("DHAI_bob_cards_width_random")
    assert factory.short_property_name == "cards_width_random"
    assert factory.socket_name == "Width random"


