@pytest.mark.parametrize("name, asset, short_name, other_asset, other_short_name",
                         [("DHAI_afro_roll_length", "afro", "roll_length", "afro_roll", "length"),
                          ("DHAI_long_cards_density", "long", "cards_density", "long_cards", "density")])
def test_ambiguous_name_is_read_by_the_asset_on_the_character(scratch, name, asset, short_name, other_asset,
                                                              other_short_name):
    """The name alone can be read two ways, so the asset which is actually on the character decides."""
    factory = Factory(name)
    assert (factory.hair_object_name, factory.short_property_name) == (asset, short_name), "the default reading"

    body = link(bpy.data.objects.new(f"hp_reading_{asset}", bpy.data.meshes.new(f"hp_reading_{asset}")))
    _child(body, other_asset)
    reading = factory.resolve(body)
    assert (reading.hair_object_name, reading.short_property_name) == (other_asset, other_short_name)

    other_body = link(bpy.data.objects.new(f"hp_reading_{other_asset}", bpy.data.meshes.new("hp_reading_other")))
    _child(other_body, asset)
    reading = factory.resolve(other_body)
    assert (reading.hair_object_name, reading.short_property_name) == (asset, short_name)


def test_ambiguous_setting_drives_the_asset_which_is_there(stand_in, asset_name):
    """"<asset>_color_noise_scale" could be the slider "noise_scale" of "<asset>_color", the getter and setter have
    to pick the colour setting when "<asset>" is the one on the character."""
    _hair_obj, _group, group_node = _hair_shader_object(stand_in, asset_name)
    name = f"{asset_name}_color_noise_scale"
    HAIR_PROPERTIES.set_value_dynamic(name, 30.0, {"name": name, "type": "float", "default": 250.0,
                                                   "description": "Noise Scale", "min": 0.0, "max": 500.0}, stand_in)
    assert group_node.inputs["Noise Scale"].default_value == pytest.approx(30.0)
    group_node.inputs["Noise Scale"].default_value = 75.0
    assert HAIR_PROPERTIES.get_value(name, None, entity_reference=stand_in) == pytest.approx(75.0)


