def test_card_settings_are_remembered_and_merged(stand_in, asset_name):
    """A snapshot only has the sockets of the current mode, so it is merged into what was remembered before."""
    assert hp.read_cards_settings(stand_in, asset_name) == {}
    hp.remember_cards_settings(stand_in, asset_name, {"cards_segments": 12, "cards_width": 0.05})
    merged = hp.remember_cards_settings(stand_in, asset_name, {"cards_taper": 0.8, "cards_width": 0.07})
    assert merged == {"cards_segments": 12, "cards_width": 0.07, "cards_taper": 0.8}
    assert hp.read_cards_settings(stand_in, asset_name) == merged


def test_card_settings_are_forgotten(stand_in, asset_name):
    hp.remember_cards_settings(stand_in, asset_name, {"cards_segments": 12})
    hp.forget_cards_settings(stand_in, asset_name)
    assert hp.read_cards_settings(stand_in, asset_name) == {}
    # Forgetting twice is fine
    hp.forget_cards_settings(stand_in, asset_name)


