def test_settings_survive_a_fresh_session(stand_in, asset_name):
    """Dynamic properties are registered on the Object type at runtime, which a new blender process starts without.

    Dropping the registration simulates that: the stored values, enums included, have to come back unchanged.
    """
    config_set = HAIR_PROPERTIES
    hp.create_cards_bake_properties(config_set, stand_in, asset_name)
    hp.create_cards_config_properties(config_set, stand_in, asset_name)
    setattr(stand_in, f"DHAI_{asset_name}_cards_resolution", 512)
    setattr(stand_in, f"DHAI_{asset_name}_cards_light_mode", cg.LIGHT_MODE_ACROSS_STRANDS)
    setattr(stand_in, f"DHAI_{asset_name}_cards_mode", cg.CARDS_MODE_SHELL)

    prefix = config_set.dynamic_prefix + asset_name
    for name in [prop.identifier for prop in stand_in.bl_rna.properties if prop.identifier.startswith(prefix)]:
        if hasattr(bpy.types.Object, name):
            delattr(bpy.types.Object, name)
        config_set._properties_by_full_name.pop(name, None)
        config_set._properties_by_short_name.pop(name[len(config_set.dynamic_prefix):], None)
    config_set._dynamic_keys_cache.clear()
    assert not hasattr(bpy.types.Object, f"DHAI_{asset_name}_cards_resolution")

    assert config_set.rebuild_dynamic_properties(stand_in) > 0
    config_set._dynamic_keys_cache.clear()
    assert config_set.get_value(f"{asset_name}_cards_resolution", 0, entity_reference=stand_in) == 512
    assert hp.get_light_mode(config_set, stand_in, asset_name) == cg.LIGHT_MODE_ACROSS_STRANDS
    assert hp.get_cards_mode(config_set, stand_in, asset_name) == cg.CARDS_MODE_SHELL


