def test_find_cards_socket_identifier(scratch):
    node_group = cg.build_tiles_node_group("hp_sockets", cg.SELECTION_METHOD_RANDOM, None)
    identifier = hp.find_cards_socket_identifier(node_group, "Segments")
    assert identifier is not None
    found = next(item for item in node_group.interface.items_tree if getattr(item, "identifier", None) == identifier)
    assert found.name == "Segments" and found.in_out == "INPUT"
    # Geometry is both an input and an output, only the input counts
    geometry = hp.find_cards_socket_identifier(node_group, "Geometry")
    assert next(item for item in node_group.interface.items_tree
                if getattr(item, "identifier", None) == geometry).in_out == "INPUT"
    assert hp.find_cards_socket_identifier(node_group, "Taper") is None
    assert hp.find_cards_socket_identifier(None, "Segments") is None


