    assert hp.get_cards_object(asset_name) == card_obj
    assert not hp.has_cards_generator(asset_name), "hand modelled cards from the pack have no generator"
    card_obj.modifiers.new(name=hp.CARDS_MODIFIER_NAME, type='NODES')
