def test_custom_surface_lookup(stand_in, asset_name):
    assert hp.resolve_custom_surface(HAIR_PROPERTIES, stand_in, asset_name) is None
    hp.create_cards_bake_properties(HAIR_PROPERTIES, stand_in, asset_name)

    def pick(name):
        setattr(stand_in, f"DHAI_{asset_name}_cards_custom_mesh", name)
        return hp.resolve_custom_surface(HAIR_PROPERTIES, stand_in, asset_name)

    assert pick("") is None
    assert pick("there is no such object") is None
    link(bpy.data.objects.new(f"{asset_name}_empty", None))
    assert pick(f"{asset_name}_empty") is None, "only a mesh can carry a texture"
    mesh_obj = make_grid(f"{asset_name}_target")
    assert pick(mesh_obj.name) == mesh_obj


def test_custom_mesh_gets_its_materials_back(scratch, asset_name):
    surface = make_grid(f"{asset_name}_custom")
    first, second = make_material(f"{asset_name}_first"), make_material(f"{asset_name}_second")
    surface.data.materials.append(first)
    surface.data.materials.append(None)
    surface.data.materials.append(second)

    hp.remember_custom_mesh_materials(surface)
    surface.data.materials.clear()
    surface.data.materials.append(make_material(f"{asset_name}_baked"))
    bpy.data.materials.remove(second)

    assert hp.restore_custom_mesh_materials(surface)
    assert [slot.material for slot in surface.material_slots] == [first, None, None], \
        "a material deleted in the meantime comes back as an empty slot"
    assert hp.CUSTOM_MESH_MATERIALS_PROPERTY not in surface
    assert not hp.restore_custom_mesh_materials(surface), "nothing is remembered any more"


