def _tiles_cards(basemesh, asset_name):
    """A card object with a tiles generator, a child of the basemesh like the generate operator makes it."""
    card_obj = _child(basemesh, f"{asset_name}_cards", bpy.data.hair_curves.new(f"{asset_name}_cards"))
    modifier = card_obj.modifiers.new(name=hp.CARDS_MODIFIER_NAME, type='NODES')
    modifier.node_group = cg.build_tiles_node_group(f"{asset_name}_cards_{hp.CARDS_MODIFIER_NAME}",
                                                    cg.SELECTION_METHOD_RANDOM, None)
    return card_obj, modifier


def test_card_setting_writes_through_to_the_generator(stand_in, asset_name):
    from ... import ModifierService

    _card_obj, modifier = _tiles_cards(stand_in, asset_name)
    hp.create_cards_properties(HAIR_PROPERTIES, stand_in, asset_name)
    setattr(stand_in, f"DHAI_{asset_name}_cards_segments", 17)
    identifier = hp.find_cards_socket_identifier(modifier.node_group, "Segments")
    assert ModifierService.get_node_group_input(modifier, identifier) == 17
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_segments", 0, entity_reference=stand_in) == 17

    snapshot = hp.snapshot_cards_properties(HAIR_PROPERTIES, stand_in, asset_name)
    assert snapshot["cards_segments"] == 17
    assert "cards_taper" not in snapshot, "a socket the mode does not have must not be remembered as its default"
    assert json.dumps(snapshot), "the snapshot is stored as json, so it has to hold plain python values"


def test_card_setting_without_a_socket_is_ignored(stand_in, asset_name):
    """Every mode only has some of the sockets. The rest read their default and ignore writes."""
    _tiles_cards(stand_in, asset_name)
    hp.create_cards_properties(HAIR_PROPERTIES, stand_in, asset_name)
    setattr(stand_in, f"DHAI_{asset_name}_cards_taper", 0.9)
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_taper", None, entity_reference=stand_in) == pytest.approx(0.3)


def test_card_setting_without_cards_reads_its_default(stand_in, asset_name):
    hp.create_cards_properties(HAIR_PROPERTIES, stand_in, asset_name)
    setattr(stand_in, f"DHAI_{asset_name}_cards_segments", 30)
    assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_segments", None, entity_reference=stand_in) == 8


def test_card_setting_only_reaches_the_cards_of_its_own_character(scratch, asset_name):
    """The same asset on a second character has the same card name, so the lookup must not be global."""
    first = link(bpy.data.objects.new(f"{asset_name}_first", bpy.data.meshes.new(f"{asset_name}_first")))
    second = link(bpy.data.objects.new(f"{asset_name}_second", bpy.data.meshes.new(f"{asset_name}_second")))
    try:
        _tiles_cards(first, asset_name)
        hp.create_cards_properties(HAIR_PROPERTIES, second, asset_name)
        setattr(second, f"DHAI_{asset_name}_cards_segments", 40)
        assert HAIR_PROPERTIES.get_value(f"{asset_name}_cards_segments", None, entity_reference=second) == 8
    finally:
        HAIR_PROPERTIES.remove_dynamic_keys_with_prefix(f"{asset_name}_", second)


def _hair_shader_object(basemesh, asset_name):
    """A hair object with a material holding a "Hair shader EEVEE" group, like the pack assets have."""
    group = bpy.data.node_groups.new(f"Hair shader EEVEE {asset_name}", 'ShaderNodeTree')
    group.interface.new_socket("Color 1", in_out='INPUT', socket_type='NodeSocketColor')
    group.interface.new_socket("Noise Scale", in_out='INPUT', socket_type='NodeSocketFloat')
    colour = group.nodes.new('ShaderNodeRGB')
    colour.name = "Colour"
    for name in ("Principled", "Hair BSDF"):
        shader = group.nodes.new('ShaderNodeBsdfPrincipled')
        shader.name = name
        group.links.new(colour.outputs['Color'], shader.inputs[0])

    material = bpy.data.materials.new(f"{asset_name}_material")
    material.use_nodes = True
    group_node = material.node_tree.nodes.new('ShaderNodeGroup')
    group_node.node_tree = group

    hair_obj = _child(basemesh, asset_name)
    hair_obj.data.materials.append(material)
    return hair_obj, group, group_node


def test_colour_writes_through_to_the_hair_shader(stand_in, asset_name):
    _hair_obj, _group, group_node = _hair_shader_object(stand_in, asset_name)
    name = f"{asset_name}_color1"
    HAIR_PROPERTIES.set_value_dynamic(name, [0.5, 0.1, 0.1, 1.0], {"name": name, "type": "color",
                                                                   "description": "Color 1",
                                                                   "default": [0.0, 0.0, 0.0, 1.0]}, stand_in)
    assert list(group_node.inputs["Color 1"].default_value) == pytest.approx([0.5, 0.1, 0.1, 1.0])
    group_node.inputs["Color 1"].default_value = (0.2, 0.3, 0.4, 1.0)
    assert list(HAIR_PROPERTIES.get_value(name, None, entity_reference=stand_in)) == pytest.approx([0.2, 0.3, 0.4, 1.0])


