def _texture_file(tmp_path, name="fur_texture.png"):
    path = os.path.join(str(tmp_path), name)
    image = bpy.data.images.new("hp_texture_source", 4, 4)
    image.pixels = [1.0, 0.0, 0.0, 1.0] * 16
    image.filepath_raw = path
    image.file_format = 'PNG'
    image.save()
    bpy.data.images.remove(image)
    return path


def _colour_sources(group):
    return sorted({link.from_node.bl_idname for node in group.nodes if node.bl_idname == 'ShaderNodeBsdfPrincipled'
                   for link in node.inputs[0].links})


def _fur_texture_properties(basemesh, asset_name):
    for name, proptype, default in (("use_texture", "boolean", False), ("texture_path", "path", "")):
        full = f"{asset_name}_{name}"
        FUR_PROPERTIES.set_value_dynamic(full, default, {"name": full, "type": proptype, "default": default,
                                                         "description": name}, basemesh)


def test_fur_texture_switches_the_shader_over_and_back(stand_in, asset_name, tmp_path):
    _hair_obj, group, _group_node = _hair_shader_object(stand_in, asset_name)
    _fur_texture_properties(stand_in, asset_name)
    prefix = FUR_PROPERTIES.dynamic_prefix

    def use_texture():
        return FUR_PROPERTIES.get_value(f"{asset_name}_use_texture", None, entity_reference=stand_in)

    assert not use_texture()
    assert FUR_PROPERTIES.get_value(f"{asset_name}_texture_path", None, entity_reference=stand_in) == \
        "Select texture path"

    path = _texture_file(tmp_path)
    setattr(stand_in, f"{prefix}{asset_name}_texture_path", path)
    assert use_texture(), "loading a texture puts it to use"
    assert _colour_sources(group) == ['ShaderNodeTexImage']
    assert os.path.normcase(FUR_PROPERTIES.get_value(f"{asset_name}_texture_path", None, entity_reference=stand_in)) \
        == os.path.normcase(path)

    setattr(stand_in, f"{prefix}{asset_name}_use_texture", True)
    setattr(stand_in, f"{prefix}{asset_name}_use_texture", False)
    assert not use_texture()
    assert _colour_sources(group) == ['ShaderNodeRGB'], "switching on twice must not lose the colours"

    setattr(stand_in, f"{prefix}{asset_name}_use_texture", True)
    assert _colour_sources(group) == ['ShaderNodeTexImage']


def test_fur_texture_with_a_bad_path_goes_back_to_the_colours(stand_in, asset_name, tmp_path):
    _hair_obj, group, _group_node = _hair_shader_object(stand_in, asset_name)
    _fur_texture_properties(stand_in, asset_name)
    prefix = FUR_PROPERTIES.dynamic_prefix
    setattr(stand_in, f"{prefix}{asset_name}_texture_path", _texture_file(tmp_path))
    setattr(stand_in, f"{prefix}{asset_name}_texture_path", os.path.join(str(tmp_path), "missing.png"))
    assert _colour_sources(group) == ['ShaderNodeRGB']
    assert not any(node.bl_idname == 'ShaderNodeTexImage' for node in group.nodes)


def test_switching_texture_on_without_a_texture_does_nothing(stand_in, asset_name):
    _hair_obj, group, _group_node = _hair_shader_object(stand_in, asset_name)
    _fur_texture_properties(stand_in, asset_name)
    setattr(stand_in, f"{FUR_PROPERTIES.dynamic_prefix}{asset_name}_use_texture", True)
    assert _colour_sources(group) == ['ShaderNodeRGB']
